// AIEI Drill-Down Interaction Logic
function scoreColor(v) {
  if (v >= 0.70) return '#FF6C37';
  if (v >= 0.40) return '#6B4FBB';
  return '#E34F8C';
}

function toggleDrill(dim) {
  var panel = document.getElementById('drill-' + dim);
  if (!panel) return;
  panel.classList.toggle('open');
  if (panel.classList.contains('open')) {
    switchTab(dim, 'why');
  }
}

function switchTab(dim, tab) {
  var tabs = ['why', 'sources', 'benchmark', 'improve'];
  tabs.forEach(function(t) {
    var el = document.getElementById(dim + '-' + t);
    var btn = document.getElementById(dim + '-tab-' + t);
    if (el) el.className = t === tab ? 'tab-content active' : 'tab-content';
    if (btn) btn.className = t === tab ? 'tab active' : 'tab';
  });
}

function renderFactorTable(factors) {
  if (!factors || factors.length === 0) return '<div class="empty-state">No factor data available</div>';
  var html = '<table class="factor-table"><thead><tr><th>Factor</th><th>Value</th><th>Impact</th><th>Source</th></tr></thead><tbody>';
  factors.forEach(function(f) {
    var color = scoreColor(1 - Math.abs(1 - (f.value || 0)));
    html += '<tr>';
    html += '<td><strong>' + f.name + '</strong></td>';
    html += '<td style="color:' + color + ';font-weight:700;">' + (f.value !== undefined ? f.value.toFixed(4) : 'N/A') + '</td>';
    html += '<td>' + (f.formula_contribution || '') + '</td>';
    html += '<td><span class="connector-badge ' + (f.source === 'mock' ? 'mock' : 'live') + '">' + (f.source || 'mock').toUpperCase() + '</span></td>';
    html += '</tr>';
    if (f.raw_metric) {
      html += '<tr><td colspan="4" style="padding:2px 8px 8px 24px;font-size:11px;opacity:0.7;">' + f.raw_metric + '</td></tr>';
    }
  });
  html += '</tbody></table>';
  return html;
}

function renderConnectors(connectors) {
  if (!connectors || connectors.length === 0) return '<div class="empty-state">No connector data available. Run the Scoring Pipeline first.</div>';
  var html = '';
  connectors.forEach(function(c) {
    var isLive = c.status === 'LIVE';
    html += '<div class="connector-detail">';
    html += '<span class="connector-badge ' + (isLive ? 'live' : 'mock') + '">' + c.status + '</span> ';
    html += '<strong>' + c.name + '</strong>';
    if (c.endpoint) html += '<div class="endpoint">' + c.endpoint + '</div>';
    if (c.metrics && c.metrics.length) html += '<div>Metrics: ' + c.metrics.join(', ') + '</div>';
    if (c.raw_values) {
      var vals = [];
      Object.keys(c.raw_values).forEach(function(k) { vals.push(k + '=' + c.raw_values[k]); });
      if (vals.length) html += '<div>Pulled: ' + vals.join(', ') + '</div>';
    }
    if (!isLive && c.enable_hint) html += '<div style="margin-top:4px;color:#FF6C37;">To enable: ' + c.enable_hint + '</div>';
    html += '</div>';
  });
  return html;
}

function renderBenchmark(dim, score, benchmarks) {
  if (!benchmarks) return '<div class="empty-state">Benchmark data not loaded. Run Setup collection first.</div>';
  var b = benchmarks[dim];
  if (!b) return '<div class="empty-state">No benchmarks for this dimension.</div>';

  var avg = b.industry_avg || 0;
  var top = b.top_quartile || (avg + 0.20);
  var avgPct = Math.round(avg * 100);
  var topPct = Math.round(top * 100);
  var scorePct = Math.round(score * 100);

  var html = '<div style="margin-bottom:16px;">';
  html += '<div style="font-size:12px;margin-bottom:4px;"><strong>Your Score:</strong> <span style="color:' + scoreColor(score) + ';font-weight:700;">' + score.toFixed(2) + '</span></div>';

  // Industry avg bar
  html += '<div class="bench-label">Industry Average: ' + avg.toFixed(2) + '</div>';
  html += '<div class="bench-track">';
  html += '<div style="width:' + avgPct + '%;height:100%;background:var(--pm-gray-400);border-radius:4px;"></div>';
  html += '<div class="bench-marker" style="left:' + scorePct + '%;background:' + scoreColor(score) + ';"></div>';
  html += '</div>';

  // Top quartile bar
  if (b.top_quartile) {
    html += '<div class="bench-label">Top Quartile: ' + top.toFixed(2) + '</div>';
    html += '<div class="bench-track">';
    html += '<div style="width:' + topPct + '%;height:100%;background:var(--pm-purple);border-radius:4px;"></div>';
    html += '<div class="bench-marker" style="left:' + scorePct + '%;background:' + scoreColor(score) + ';"></div>';
    html += '</div>';
  }

  // DORA thresholds for R and L
  if (b.dora_elite) {
    html += '<div style="margin-top:12px;"><strong style="font-size:11px;">DORA Thresholds</strong></div>';
    var doraItems = [];
    Object.keys(b.dora_elite).forEach(function(k) { doraItems.push(k + ': ' + b.dora_elite[k]); });
    html += '<div style="font-size:11px;color:var(--pm-gray-400);">Elite: ' + doraItems.join(' | ') + '</div>';
  }

  html += '</div>';

  // Certified insights
  if (b.postman_certified) {
    html += '<div class="pm-insight">';
    html += '<div class="pm-insight-header">Postman Certified Insight</div>';
    var keys = Object.keys(b.postman_certified);
    keys.forEach(function(k) {
      html += '<div style="margin-bottom:4px;">' + b.postman_certified[k] + '</div>';
    });
    html += '<div class="pm-insight-source">Source: ' + (b.source || 'Postman State of the API') + '</div>';
    html += '</div>';
  }

  return html;
}

function renderImprove(dim, detail, benchmarks) {
  if (!detail) return '<div class="empty-state">No improvement data. Run Scoring Pipeline first.</div>';
  var html = '';

  // Weakest factor callout
  if (detail.weakest_factor) {
    var weakFactor = null;
    (detail.factors || []).forEach(function(f) { if (f.key === detail.weakest_factor) weakFactor = f; });
    if (weakFactor) {
      html += '<div style="margin-bottom:12px;">';
      html += '<div style="font-size:11px;text-transform:uppercase;letter-spacing:2px;color:var(--pm-orange);margin-bottom:4px;">#1 Priority</div>';
      html += '<div style="font-size:14px;font-weight:700;">' + weakFactor.name + '</div>';
      html += '<div style="font-size:12px;margin-top:4px;">Current value: <span style="color:' + scoreColor(weakFactor.value || 0) + ';font-weight:700;">' + (weakFactor.value || 0).toFixed(4) + '</span></div>';
      if (weakFactor.weight_description) html += '<div style="font-size:11px;margin-top:2px;opacity:0.7;">' + weakFactor.weight_description + '</div>';
      html += '</div>';
    }
  }

  // AIEI lift projection
  if (detail.projected_lift) {
    html += '<div style="background:rgba(255,108,55,0.1);border-radius:8px;padding:10px;margin:8px 0;font-size:12px;">';
    html += '<strong>Projected AIEI lift:</strong> +' + detail.projected_lift.toFixed(4) + ' if this factor reaches target';
    html += '</div>';
  }

  // Postman certified recommendation
  var b = benchmarks ? benchmarks[dim] : null;
  if (b && b.improvement_benchmarks) {
    html += '<div class="pm-insight">';
    html += '<div class="pm-insight-header">Postman Certified Recommendation</div>';
    Object.keys(b.improvement_benchmarks).forEach(function(k) {
      html += '<div style="margin-bottom:4px;">' + b.improvement_benchmarks[k] + '</div>';
    });
    html += '<div class="pm-insight-source">Source: ' + (b.source || 'Postman State of the API') + '</div>';
    html += '</div>';
  }

  // Unconfigured connectors as improvement opportunities
  if (detail.connectors_used) {
    var mocks = detail.connectors_used.filter(function(c) { return c.status === 'MOCK'; });
    if (mocks.length > 0) {
      html += '<div style="margin-top:12px;font-size:11px;text-transform:uppercase;letter-spacing:2px;margin-bottom:6px;">Connect More Data Sources</div>';
      mocks.forEach(function(m) {
        html += '<div class="connector-detail">';
        html += '<span class="connector-badge mock">MOCK</span> <strong>' + m.name + '</strong>';
        if (m.enable_hint) html += '<div style="color:#FF6C37;margin-top:4px;">' + m.enable_hint + '</div>';
        html += '</div>';
      });
    }
  }

  return html;
}

