    html += '<tr>';
    html += '<td><strong>' + f.name + '</strong></td>';
    html += '<td style="color:' + color + ';font-weight:700;">' + (f.value !== undefined ? f.value.toFixed(4) : 'N/A') + '</td>';
    html += '<td>' + (f.formula_contribution || '') + '</td>';
    html += '<td><span class="connector-badge ' + (f.source === 'mock' ? 'mock' : 'live') + '">' + (f.source || 'mock').toUpperCase() + '</span></td>';
    html += '</tr>';
    if (f.raw_metric) {
      html += '<tr><td colspan="4" style="padding:2px 8px 8px 24px;font-size:11px;opacity:0.7;">' + f.raw_metric + '</td></tr>';
    }
  });
  html += '</tbody></table>';
  return html;
}

function renderConnectors(connectors) {
  if (!connectors || connectors.length === 0) return '<div class="empty-state">No connector data available. Run the Scoring Pipeline first.</div>';
  var html = '';
  connectors.forEach(function(c) {
    var isLive = c.status === 'LIVE';
    html += '<div class="connector-detail">';
    html += '<span class="connector-badge ' + (isLive ? 'live' : 'mock') + '">' + c.status + '</span> ';
    html += '<strong>' + c.name + '</strong>';
    if (c.endpoint) html += '<div class="endpoint">' + c.endpoint + '</div>';
    if (c.metrics && c.metrics.length) html += '<div>Metrics: ' + c.metrics.join(', ') + '</div>';
    if (c.raw_values) {
      var vals = [];
      Object.keys(c.raw_values).forEach(function(k) { vals.push(k + '=' + c.raw_values[k]); });
      if (vals.length) html += '<div>Pulled: ' + vals.join(', ') + '</div>';
    }
    if (!isLive && c.enable_hint) html += '<div style="margin-top:4px;color:#FF6C37;">To enable: ' + c.enable_hint + '</div>';
    html += '</div>';
  });
  return html;
}

function renderBenchmark(dim, score, benchmarks) {
  if (!benchmarks) return '<div class="empty-state">Benchmark data not loaded. Run Setup collection first.</div>';
  var b = benchmarks[dim];
  if (!b) return '<div class="empty-state">No benchmarks for this dimension.</div>';

  var avg = b.industry_avg || 0;
  var top = b.top_quartile || (avg + 0.20);
  var avgPct = Math.round(avg * 100);
  var topPct = Math.round(top * 100);
  var scorePct = Math.round(score * 100);

  var html = '<div style="margin-bottom:16px;">';
  html += '<div style="font-size:12px;margin-bottom:4px;"><strong>Your Score:</strong> <span style="color:' + scoreColor(score) + ';font-weight:700;">' + score.toFixed(2) + '</span></div>';

  html += '<div class="bench-label">Industry Average: ' + avg.toFixed(2) + '</div>';
  html += '<div class="bench-track">';
  html += '<div style="width:' + avgPct + '%;height:100%;background:var(--pm-gray-400);border-radius:4px;"></div>';
  html += '<div class="bench-marker" style="left:' + scorePct + '%;background:' + scoreColor(score) + ';"></div>';
  html += '</div>';

  if (b.top_quartile) {
    html += '<div class="bench-label">Top Quartile: ' + top.toFixed(2) + '</div>';
    html += '<div class="bench-track">';
    html += '<div style="width:' + topPct + '%;height:100%;background:var(--pm-purple);border-radius:4px;"></div>';
    html += '<div class="bench-marker" style="left:' + scorePct + '%;background:' + scoreColor(score) + ';"></div>';
    html += '</div>';
  }

  if (b.dora_elite) {
    html += '<div style="margin-top:12px;"><strong style="font-size:11px;">DORA Thresholds</strong></div>';
    var doraItems = [];
    Object.keys(b.dora_elite).forEach(function(k) { doraItems.push(k + ': ' + b.dora_elite[k]); });
    html += '<div style="font-size:11px;color:var(--pm-gray-400);">Elite: ' + doraItems.join(' | ') + '</div>';
  }

  html += '</div>';

  if (b.postman_certified) {
    html += '<div class="pm-insight">';
    html += '<div class="pm-insight-header">Postman Certified Insight</div>';
    var keys = Object.keys(b.postman_certified);
    keys.forEach(function(k) {
      html += '<div style="margin-bottom:4px;">' + b.postman_certified[k] + '</div>';
    });
    html += '<div class="pm-insight-source">Source: ' + (b.source || 'Postman State of the API') + '</div>';
    html += '</div>';
  }

  return html;
}

function renderImprove(dim, detail, benchmarks) {
  if (!detail) return '<div class="empty-state">No improvement data. Run Scoring Pipeline first.</div>';
  var html = '';

  if (detail.weakest_factor) {
    var weakFactor = null;
    (detail.factors || []).forEach(function(f) { if (f.key === detail.weakest_factor) weakFactor = f; });
    if (weakFactor) {
      html += '<div style="margin-bottom:12px;">';
      html += '<div style="font-size:11px;text-transform:uppercase;letter-spacing:2px;color:var(--pm-orange);margin-bottom:4px;">#1 Priority</div>';
      html += '<div style="font-size:14px;font-weight:700;">' + weakFactor.name + '</div>';
      html += '<div style="font-size:12px;margin-top:4px;">Current value: <span style="color:' + scoreColor(weakFactor.value || 0) + ';font-weight:700;">' + (weakFactor.value || 0).toFixed(4) + '</span></div>';
      if (weakFactor.weight_description) html += '<div style="font-size:11px;margin-top:2px;opacity:0.7;">' + weakFactor.weight_description + '</div>';
      html += '</div>';
    }
  }

  if (detail.projected_lift) {
    html += '<div style="background:rgba(255,108,55,0.1);border-radius:8px;padding:10px;margin:8px 0;font-size:12px;">';
    html += '<strong>Projected AIEI lift:</strong> +' + detail.projected_lift.toFixed(4) + ' if this factor reaches target';
    html += '</div>';
  }

  var b = benchmarks ? benchmarks[dim] : null;
  if (b && b.improvement_benchmarks) {
    html += '<div class="pm-insight">';
    html += '<div class="pm-insight-header">Postman Certified Recommendation</div>';
    Object.keys(b.improvement_benchmarks).forEach(function(k) {
      html += '<div style="margin-bottom:4px;">' + b.improvement_benchmarks[k] + '</div>';
    });
    html += '<div class="pm-insight-source">Source: ' + (b.source || 'Postman State of the API') + '</div>';
    html += '</div>';
  }

  if (detail.connectors_used) {
    var mocks = detail.connectors_used.filter(function(c) { return c.status === 'MOCK'; });
    if (mocks.length > 0) {
      html += '<div style="margin-top:12px;font-size:11px;text-transform:uppercase;letter-spacing:2px;margin-bottom:6px;">Connect More Data Sources</div>';
      mocks.forEach(function(m) {
        html += '<div class="connector-detail">';
        html += '<span class="connector-badge mock">MOCK</span> <strong>' + m.name + '</strong>';
        if (m.enable_hint) html += '<div style="color:#FF6C37;margin-top:4px;">' + m.enable_hint + '</div>';
        html += '</div>';
      });
    }
  }

  return html;
}
</script>
</head>
<body>

<div class="cio-wrap">
  <header class="cio-header">
    <div class="header-brand">POSTMAN</div>
    <h1 class="header-title">AI EFFECTIVENESS INDEX</h1>
    <div class="header-accent"></div>
  </header>

  <section class="cio-hero">
    <div class="header-score" style="color: {{aieiColor}};">{{aieiScore}}</div>
    <div class="header-class" style="color: {{aieiColor}};">{{aieiClass}}</div>
    <p class="header-verdict">{{aieiVerdict}}</p>
  </section>

  <div class="roi-box">
    <div class="roi-number">{{roiMultiple}}x ROI</div>
    <div class="roi-label">Return on AI Investment</div>
    <div class="roi-detail">{{roiDetail}}</div>
  </div>

  <div style="display:flex;gap:14px;margin-bottom:32px;flex-wrap:wrap;">
    <div style="flex:1;min-width:180px;">
      <div class="kpi-card" onclick="toggleDrill('q')">
        <div class="kpi-label">Code Quality Impact</div>
        <div class="kpi-val" style="color: {{qColor}};">{{qScore}}</div>
        <div class="kpi-meta" style="color: {{qColor}};font-weight:600;">{{qClass}}</div>
        <div class="kpi-meta">Weight: {{qWeight}}</div>
        <div class="bar"><div class="bar-fill" style="width: {{qPct}}%; background: {{qColor}};"></div></div>
      </div>
      <div id="drill-q" class="drill-panel">
        <div class="tab-bar">
          <span class="tab active" id="q-tab-why" onclick="event.stopPropagation(); switchTab('q','why');">Why</span>
          <span class="tab" id="q-tab-sources" onclick="event.stopPropagation(); switchTab('q','sources');">Sources</span>
          <span class="tab" id="q-tab-benchmark" onclick="event.stopPropagation(); switchTab('q','benchmark');">Benchmark</span>
          <span class="tab" id="q-tab-improve" onclick="event.stopPropagation(); switchTab('q','improve');">Improve</span>
        </div>
        <div id="q-why" class="tab-content active">{{{qWhy}}}</div>
        <div id="q-sources" class="tab-content">{{{qSources}}}</div>
        <div id="q-benchmark" class="tab-content">{{{qBenchmark}}}</div>
        <div id="q-improve" class="tab-content">{{{qImprove}}}</div>
      </div>
    </div>

    <div style="flex:1;min-width:180px;">
      <div class="kpi-card" onclick="toggleDrill('l')">
        <div class="kpi-label">Lead Time</div>
        <div class="kpi-val" style="color: {{lColor}};">{{lScore}}</div>
        <div class="kpi-meta" style="color: {{lColor}};font-weight:600;">{{lClass}}</div>
        <div class="kpi-meta">Weight: {{lWeight}}</div>
        <div class="bar"><div class="bar-fill" style="width: {{lPct}}%; background: {{lColor}};"></div></div>
      </div>
      <div id="drill-l" class="drill-panel">
        <div class="tab-bar">
          <span class="tab active" id="l-tab-why" onclick="event.stopPropagation(); switchTab('l','why');">Why</span>
          <span class="tab" id="l-tab-sources" onclick="event.stopPropagation(); switchTab('l','sources');">Sources</span>
          <span class="tab" id="l-tab-benchmark" onclick="event.stopPropagation(); switchTab('l','benchmark');">Benchmark</span>
          <span class="tab" id="l-tab-improve" onclick="event.stopPropagation(); switchTab('l','improve');">Improve</span>
        </div>
        <div id="l-why" class="tab-content active">{{{lWhy}}}</div>
        <div id="l-sources" class="tab-content">{{{lSources}}}</div>
        <div id="l-benchmark" class="tab-content">{{{lBenchmark}}}</div>
        <div id="l-improve" class="tab-content">{{{lImprove}}}</div>
      </div>
    </div>

    <div style="flex:1;min-width:180px;">
      <div class="kpi-card" onclick="toggleDrill('r')">
        <div class="kpi-label">Reliability</div>
        <div class="kpi-val" style="color: {{rColor}};">{{rScore}}</div>
        <div class="kpi-meta" style="color: {{rColor}};font-weight:600;">{{rClass}}</div>
        <div class="kpi-meta">Weight: {{rWeight}}</div>
        <div class="bar"><div class="bar-fill" style="width: {{rPct}}%; background: {{rColor}};"></div></div>
      </div>
      <div id="drill-r" class="drill-panel">
        <div class="tab-bar">
          <span class="tab active" id="r-tab-why" onclick="event.stopPropagation(); switchTab('r','why');">Why</span>
          <span class="tab" id="r-tab-sources" onclick="event.stopPropagation(); switchTab('r','sources');">Sources</span>
          <span class="tab" id="r-tab-benchmark" onclick="event.stopPropagation(); switchTab('r','benchmark');">Benchmark</span>
          <span class="tab" id="r-tab-improve" onclick="event.stopPropagation(); switchTab('r','improve');">Improve</span>
        </div>
        <div id="r-why" class="tab-content active">{{{rWhy}}}</div>
        <div id="r-sources" class="tab-content">{{{rSources}}}</div>
        <div id="r-benchmark" class="tab-content">{{{rBenchmark}}}</div>
        <div id="r-improve" class="tab-content">{{{rImprove}}}</div>
      </div>
    </div>

    <div style="flex:1;min-width:180px;">
      <div class="kpi-card" onclick="toggleDrill('c')">
        <div class="kpi-label">Cost Efficiency</div>
        <div class="kpi-val" style="color: {{cColor}};">{{cScore}}</div>
        <div class="kpi-meta" style="color: {{cColor}};font-weight:600;">{{cClass}}</div>
        <div class="kpi-meta">Weight: {{cWeight}}</div>
        <div class="bar"><div class="bar-fill" style="width: {{cPct}}%; background: {{cColor}};"></div></div>
      </div>
      <div id="drill-c" class="drill-panel">
        <div class="tab-bar">
          <span class="tab active" id="c-tab-why" onclick="event.stopPropagation(); switchTab('c','why');">Why</span>
          <span class="tab" id="c-tab-sources" onclick="event.stopPropagation(); switchTab('c','sources');">Sources</span>
          <span class="tab" id="c-tab-benchmark" onclick="event.stopPropagation(); switchTab('c','benchmark');">Benchmark</span>
          <span class="tab" id="c-tab-improve" onclick="event.stopPropagation(); switchTab('c','improve');">Improve</span>
        </div>
        <div id="c-why" class="tab-content active">{{{cWhy}}}</div>
        <div id="c-sources" class="tab-content">{{{cSources}}}</div>
        <div id="c-benchmark" class="tab-content">{{{cBenchmark}}}</div>
